"""Rewrite skills/edel-markets/TOOLS.md from the public MCP tools page and the live OpenAPI document.

Sources are public and need no secret, the same two the contract-names check reads:
- MCP tools: the tool table of the public MCP tools docs page named by EDEL_MCP_TOOLS_URL.
- REST routes: the live OpenAPI document of the venue named by EDEL_OPENAPI_URL.

The output depends only on those two documents, so the same inputs write the same file. A route the
docs name but the live OpenAPI document lacks is listed as not live yet, never as a route.
Exits 1 when the page has no tool table, so a layout change never empties the file.
"""

import html
import json
import os
import pathlib
import re
import sys
import urllib.request

OPENAPI_URL = os.environ.get("EDEL_OPENAPI_URL", "https://testnet.edel-api.xyz/openapi.json")
MCP_TOOLS_URL = os.environ.get(
    "EDEL_MCP_TOOLS_URL", "https://docs.edel.finance/developers/mcp/tools"
)
OUTPUT = pathlib.Path(__file__).resolve().parents[2] / "skills" / "edel-markets" / "TOOLS.md"

ROW_RE = re.compile(r"<tr><td><code>(edel_[a-z][a-z0-9_]*)</code></td><td>(.*?)</td></tr>")
CODE_RE = re.compile(r"<code>(.*?)</code>")
ROUTE_RE = re.compile(r"^(GET|POST|PUT|PATCH|DELETE) (/[A-Za-z0-9_\-/{}:.]*)$")
METHODS = {"get", "post", "put", "patch", "delete"}

HEADER = """# Edel PERPS public MCP tools

Generated by `.github/scripts/sync_public_tools.py` from the public
[MCP tools page](https://docs.edel.finance/developers/mcp/tools) and the live TestNet
`GET /openapi.json`. Do not edit by hand: the hourly `sync-public-tools` workflow rewrites it and
opens a pull request when either source changes.

Each tool calls only the REST operations beside it. Open the tool's row in
[CAPABILITIES.md](CAPABILITIES.md) for its scope and docs page, and the route description in the
live contract for its limits. "Not in the live TestNet contract yet" means the docs list the tool
but the TestNet venue does not serve its route today: treat it as unavailable there.

| Tool | REST operations |
| --- | --- |
"""


def fetch(url):
    request = urllib.request.Request(url, headers={"User-Agent": "edel-ai-config-ci"})
    with urllib.request.urlopen(request, timeout=30) as response:
        return response.read().decode("utf-8")


def normalize(path):
    path = re.sub(r"\{[^}]+\}", "{}", path)
    return re.sub(r":[A-Za-z_][A-Za-z0-9_]*", "{}", path)


def live_routes():
    spec = json.loads(fetch(OPENAPI_URL))
    return {
        f"{method.upper()} {normalize(path)}"
        for path, operations in spec["paths"].items()
        for method in operations
        if method in METHODS
    }


def tool_rows():
    rows = []
    for tool, cell in ROW_RE.findall(fetch(MCP_TOOLS_URL)):
        routes = [html.unescape(code) for code in CODE_RE.findall(cell)]
        if not routes or not all(ROUTE_RE.match(route) for route in routes):
            raise ValueError(f"{tool}: unexpected REST cell on {MCP_TOOLS_URL}")
        rows.append((tool, routes))
    return rows


def is_live(route, known):
    method, path = route.split(" ", 1)
    return f"{method} {normalize(path)}" in known


def rest_cell(routes, known):
    live = [f"`{route}`" for route in routes if is_live(route, known)]
    if not live:
        return "Not in the live TestNet contract yet."
    if len(live) < len(routes):
        live.append("and more not in the live TestNet contract yet")
    return ", ".join(live)


def render(rows, known):
    lines = [f"| `{tool}` | {rest_cell(routes, known)} |" for tool, routes in sorted(rows)]
    return HEADER + "\n".join(lines) + "\n"


def main():
    rows = tool_rows()
    if not rows:
        print(f"No tool table found at {MCP_TOOLS_URL}")
        return 1
    content = render(rows, live_routes())
    if OUTPUT.exists() and OUTPUT.read_text(encoding="utf-8") == content:
        print(f"{OUTPUT.name} already matches {len(rows)} public tools.")
        return 0
    OUTPUT.write_text(content, encoding="utf-8")
    print(f"Rewrote {OUTPUT.name} with {len(rows)} public tools.")
    return 0


if __name__ == "__main__":
    sys.exit(main())
